 865	        for (int i = 0; i < batch; ++i) {
 866	            check_cusolver(
 867	                cusolverDnSpotrf(
 868	                    handle, CUBLAS_FILL_MODE_LOWER, n,
 869	                    output.data_ptr<float>() + i * matrix_stride, n,
 870	                    workspace.data_ptr<float>(), workspace.numel(),
 871	                    info.data_ptr<int>() + i),
 872	                "cusolverDnSpotrf");
 873	        }
 874	    }
 875	
 876	    // The row-major upper factor becomes an F-contiguous lower-triangular view.
 877	    return output.transpose(-2, -1);
 878	}
