2055	__global__ void copy_panel_to_factor_kernel(
2056	        const float* source, float* factor, int leading_source) {
2057	    constexpr int tile_size = 64;
2058	    __shared__ float tile[tile_size][tile_size + 1];
2059	    const int task = static_cast<int>(blockIdx.x);
2060	    int tile_row = static_cast<int>(
2061	        (sqrtf(8.0f * static_cast<float>(task) + 1.0f) - 1.0f)
2062	        * 0.5f);
2063	    int base = tile_row * (tile_row + 1) / 2;
2064	    if (base > task) {
2065	        --tile_row;
2066	        base = tile_row * (tile_row + 1) / 2;
2067	    } else if (base + tile_row + 1 <= task) {
2068	        ++tile_row;
2069	        base = tile_row * (tile_row + 1) / 2;
2070	    }
2071	    const int tile_col = task - base;
2072	    const int row_base = tile_row * tile_size;
